240	// renderPickerOverlay draws the list overlays: a title, one entry per line, the
241	// entry in use marked and the highlighted one carrying the focus indicator.
242	func renderPickerOverlay(title string, entries []string, current string, selectedIdx int) string {
243		var b strings.Builder
244	
245		b.WriteString(theme.TitleStyle.Render(title) + "\n\n")
246	
247		for i, entry := range entries {
248			label := entry
249			if entry == current {
250				label += " (current)"
251			}
252			if i == selectedIdx {
253				b.WriteString(theme.KeyStyle.Render(theme.IconCircleSmall + " " + label))
254			} else {
255				b.WriteString(theme.Bg("  " + label))
256			}
257			b.WriteString("\n")
258		}
259	
260		return theme.OverlayBoxStyle().Render(b.String())
261	}
