263	// indexOf returns the position of want, or 0 when it is absent — the cursor has
264	// to land on a row that exists.
265	func indexOf(entries []string, want string) int {
266		for i, entry := range entries {
267			if entry == want {
268				return i
269			}
270		}
271		return 0
272	}
